/*
 Problem: 3867. Sum of GCD of Formed Pairs
 Language: cpp
 Runtime: 75 ms (49.41%)
 Memory: 162.7 MB (38.64%)
 Tags: Array, Math, Two Pointers, Sorting, Simulation, Number Theory
*/
class Solution {
public:
    long long gcdSum(vector<int>& nums) {
        vector<int> a;
        int mx = 0;

        for (const auto& x : nums) {
            mx = max(mx, x);
            a.push_back(gcd(x, mx));
        }

        sort(a.begin(), a.end());

        long long ans = 0;
        int l = 0, r = a.size() - 1;
        while (l < r) {
            ans += gcd(a[l], a[r]);
            ++l;
            --r;
        }

        return ans;
    }
};
